/// How an instruction's operand sits after its 16-bit opcode.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Layout {
    None,
    /// One byte right after the opcode.
    U8,
    /// A 2-aligned signed 16-bit offset from the end of the instruction.
    Jump,
    U16,
    /// A 4-aligned 32-bit word.
    U32,
    /// An 8-aligned 64-bit word.
    U64,
    /// A byte, then an 8-aligned 64-bit word.
    Call,
    /// A byte, then a 4-aligned 32-bit word.
    Method,
    /// A count byte, then per local a 4-aligned 32-bit hash and a byte.
    Locals,
}

impl Opcode {
    pub const fn layout(self) -> Layout {
        match self {
            Self::BitAnd
            | Self::BitOr
            | Self::BitXor
            | Self::BoolComplement
            | Self::BoolNot
            | Self::CastFieldObject
            | Self::CheckClearParams
            | Self::ClearArray
            | Self::ClearParams
            | Self::Dec
            | Self::DecTop
            | Self::Divide
            | Self::End
            | Self::EndSwitch
            | Self::Endon
            | Self::Equal
            | Self::EvalArray
            | Self::EvalArrayRef
            | Self::FirstArrayKey
            | Self::GetAnim
            | Self::GetAnimObject
            | Self::GetClasses
            | Self::GetClassesObject
            | Self::GetEmptyArray
            | Self::GetGame
            | Self::GetGameObject
            | Self::GetLevel
            | Self::GetLevelObject
            | Self::GetSelf
            | Self::GetSelfObject
            | Self::GetTime
            | Self::GetUndefined
            | Self::GetWorld
            | Self::GetWorldObject
            | Self::GetZero
            | Self::Greater
            | Self::GreaterEqual
            | Self::Inc
            | Self::IsDefined
            | Self::Less
            | Self::LessEqual
            | Self::Minus
            | Self::Modulus
            | Self::Multiply
            | Self::NextArrayKey
            | Self::NotEqual
            | Self::Notify
            | Self::Plus
            | Self::PreScriptCall
            | Self::ProfileStop
            | Self::Return
            | Self::Set
            | Self::ShiftLeft
            | Self::ShiftRight
            | Self::Size
            | Self::SkipWaittillVar
            | Self::SuperEqual
            | Self::SuperNotEqual
            | Self::Vector
            | Self::VectorScale
            | Self::Wait
            | Self::WaitRealTime
            | Self::WaitTill
            | Self::WaitTillFrameEnd => Layout::None,
            Self::CallMethodPtr
            | Self::CallPtr
            | Self::EvalLocal
            | Self::EvalLocalRef
            | Self::GetByte
            | Self::GetNegByte
            | Self::MethodThreadPtr
            | Self::SetWaittillVar
            | Self::ThreadPtr
            | Self::VectorConstant
            | Self::WaitTillMatch => Layout::U8,
            Self::Devblock
            | Self::Jump
            | Self::JumpOnFalse
            | Self::JumpOnFalseExpr
            | Self::JumpOnTrue
            | Self::JumpOnTrueExpr => Layout::Jump,
            Self::GetNegUShort | Self::GetUShort => Layout::U16,
            Self::ClearField
            | Self::EvalField
            | Self::EvalFieldRef
            | Self::EvalLevelField
            | Self::EvalLevelFieldRef
            | Self::EvalSelfField
            | Self::EvalSelfFieldRef
            | Self::GetFloat
            | Self::GetHash
            | Self::GetIString
            | Self::GetInteger
            | Self::GetString
            | Self::New
            | Self::Switch => Layout::U32,
            Self::GetAnimation | Self::GetFunction | Self::ProfileStart => Layout::U64,
            Self::CallFunc | Self::CallMethod | Self::ThreadFunc | Self::ThreadMethod => {
                Layout::Call
            }
            Self::ClassFunctionCall | Self::ClassFunctionThreadCall => Layout::Method,
            Self::Locals => Layout::Locals,
        }
    }
}

