/// The instruction an opcode value stands for; `None` for a value the game rejects as invalid, or for an
/// instruction no current script in the game uses, which is not named yet.
pub fn opcode(value: u16) -> Option<Opcode> {
    let index = *TABLE.get(usize::from(value))?;
    index.checked_sub(1).map(|i| ALL[usize::from(i)])
}

